def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([5, 5, 5, 5]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([8, 4, 6, 2, 3]), fmt([10**9, 1, 10**9, 1])]
    for n in (2, 3, 4, 6, 8, 12, 20, 30):
        for hi in (3, 10, 100):
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt(list(range(1, 100001))))
    tests.append(fmt([10**9 - i for i in range(100000)]))
    tests.append(fmt([10**9 - (i % 1000) * 7 for i in range(100000)]))
    return tests
